import {
	createEffect,
	createMemo,
	For,
	JSX,
	mergeProps,
	on,
	ParentComponent,
	Setter,
	Show,
	//	useContext,
} from "solid-js";

//import { AudioGroupContext } from "#core/ui-next/services/audio.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { createAnimationSignal, createPropsRefSignal } from "#core/ui-next/utilities/solid-utilities.js";

export interface RingMeterProps extends JSX.HTMLAttributes<HTMLDivElement> {
	min?: number;
	max: number;
	value: number;
	animationDuration?: number;
	setValue?: Setter<number>;
	audio?: {
		/** Audio group override */
		group?: string;
		onFillSound?: string;
		onRingAnimateStop?: string;
	};
	contentClass?: string;
	isTopOrigin?: boolean; //Does this ring meter start from the top (default bottom)?
	ringImage?: string; //Optional icon src for ring image
	ringTint?: string; //Optional color tint to apply to ring
	progressPips?: number[]; //Does this ring use pips? (demarkations of specific progress amounts) Default presentation is evenly spaced lines, other treatments should be handled more explicitly by those implementations
}

const RingMeterComponent: ParentComponent<RingMeterProps> = (props) => {
	const EPSILON = 0.0005;

	let ringFillStart = 0;

	const [_root, setRoot] = createPropsRefSignal<HTMLDivElement>(() => props.ref);
	const defaultProps = mergeProps({ min: 0, max: 100, value: 0, animationDuration: 1500 }, props);
	//const audioContext = useContext(AudioGroupContext);
	const reactiveDuration = createMemo(() => defaultProps.animationDuration);

	// eslint-disable-next-line solid/reactivity
	const [animationTimeElapsed, isAnimating, setIsAnimating] = createAnimationSignal(reactiveDuration);

	const fill = createMemo(() => {
		const minValue = defaultProps.min;
		const maxValue = defaultProps.max;

		if (maxValue - minValue <= 0) {
			return 0;
		} else {
			const value = Math.max(Math.min(maxValue, defaultProps.value), minValue);
			return (value - minValue) / (maxValue - minValue);
		}
	});

	const easedFill = createMemo(() => {
		// Prevent the divide by 0.
		if (props.animationDuration == 0) {
			return 0;
		}

		const timeElapsed = Math.min(animationTimeElapsed(), defaultProps.animationDuration);
		const cubicEaseFactor = Math.pow(1 - timeElapsed / defaultProps.animationDuration, 3);
		return fill() - (fill() - ringFillStart) * cubicEaseFactor;
	});

	const leftHidden = createMemo(() => {
		if (!props.isTopOrigin) {
			return easedFill() <= EPSILON;
		} else {
			return easedFill() <= 0.5;
		}
	});

	const rightHidden = createMemo(() => {
		if (!props.isTopOrigin) {
			return easedFill() <= 0.5;
		} else {
			return easedFill() <= EPSILON;
		}
	});

	const fillDegreesLeft = createMemo(() => {
		if (!props.isTopOrigin) {
			return easedFill() < 0.5 ? 180 - easedFill() * 360 : 0;
		} else {
			return easedFill() >= 0.5 ? 180 - (easedFill() - 0.5) * 360 : 0;
		}
	});

	const fillDegreesRight = createMemo(() => {
		if (!props.isTopOrigin) {
			return easedFill() >= 0.5 ? 180 - (easedFill() - 0.5) * 360 : 0;
		} else {
			return easedFill() < 0.5 ? 180 - easedFill() * 360 : 0;
		}
	});

	function playFillSound() {
		if (defaultProps.animationDuration > 0) {
			// Temp disabled, needs work
			//audioContext().playSound("data-audio-ring-animate-start", root());
		}
	}

	function playStopSound() {
		if (defaultProps.animationDuration > 0) {
			// Temp disabled, needs work
			//audioContext().playSound("data-audio-ring-animate-stop", root());
		}
	}

	function calculatePipPositionAndRotation(pipNum: number): number[] {
		let x = 0;
		let y = 0;
		let rotation = 0;

		const pipPercent = pipNum / props.max;
		const angle = Math.PI * 2 * pipPercent - Math.PI / 2;
		x = Math.cos(angle) * 50 + 50;
		y = Math.sin(angle) * 50 + 50;
		rotation = ((angle + Math.PI) * 180) / Math.PI + 90;

		return [x, y, rotation];
	}

	createEffect(
		on(
			() => defaultProps.value,
			() => {
				if (isAnimating()) {
					// If value changed while animating, set the animation start to current animated ring fill
					ringFillStart = easedFill();
				} else {
					setIsAnimating(true);
					playFillSound();
				}
			},
		),
	);

	createEffect(
		on(
			() => isAnimating(),
			(isAnimating) => {
				if (!isAnimating) {
					ringFillStart = fill();
					playStopSound();
				}
			},
		),
	);

	return (
		<div
			ref={setRoot}
			class={`fxs-ring-meter relative ${props.class}`}
			data-audio-group-ref={props.audio?.group}
			data-audio-fill-sound-ref={props.audio?.onFillSound}
			data-audio-ring-animate-stop-ref={props.audio?.onRingAnimateStop}
			data-name="RingMeter"
		>
			<div
				class={`fxs-ring-meter__content ${props.contentClass ?? "flex items-center justify-center w-full h-full"}`}
			>
				{props.children}
			</div>
			<div class="fxs-ring-meter__ring">
				<div
					class="fxs-ring-meter__mask-left"
					classList={{ "opacity-0": leftHidden() }}
					style={{ transform: `rotate(-${fillDegreesLeft()}deg)` }}
				>
					<div
						class="fxs-ring-meter__ring-left"
						style={{
							transform: `rotate(${fillDegreesLeft()}deg)`,
							"background-image": props.ringImage ?? `url("blp:hud_small-progress_bar.png")`,
							"background-size": "cover",
							"background-position": "left",
							// eslint-disable-next-line solid/style-prop
							"fxs-background-image-tint": props.ringTint ?? "",
						}}
					/>
				</div>
				<div
					class="fxs-ring-meter__mask-right"
					classList={{ "opacity-0": rightHidden() }}
					style={{ transform: `rotate(-${fillDegreesRight()}deg)` }}
				>
					<div
						class="fxs-ring-meter__ring-right"
						style={{
							transform: `rotate(${fillDegreesRight()}deg)`,
							"background-image": props.ringImage ?? `url("blp:hud_small-progress_bar.png")`,
							"background-size": "cover",
							"background-position": "right",
							// eslint-disable-next-line solid/style-prop
							"fxs-background-image-tint": props.ringTint ?? "",
						}}
					/>
				</div>
				<Show when={props.progressPips && props.progressPips.length > 0}>
					<div class="absolute self-center top-px left-0 right-0 bottom-0">
						<For each={props.progressPips}>
							{(pip) => (
								<div
									class="absolute ring-meter-pip"
									style={{
										left: `${calculatePipPositionAndRotation(pip)[0]}%`,
										top: `${calculatePipPositionAndRotation(pip)[1]}%`,
										transform: `rotate(${calculatePipPositionAndRotation(pip)[2]}deg)`,
									}}
								/>
							)}
						</For>
					</div>
				</Show>
			</div>
		</div>
	);
};

export const RingMeter = ComponentRegistry.register({
	name: "RingMeter",
	createInstance: RingMeterComponent,
});
